"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[39662],{3331:(i,e,o)=>{o.d(e,{R:()=>r,x:()=>s});var a=o(36672);const n={},t=a.createContext(n);function r(i){const e=a.useContext(t);return a.useMemo((function(){return"function"==typeof i?i(e):{...e,...i}}),[e,i])}function s(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(n):i.components||n:r(i.components),a.createElement(t.Provider,{value:e},i.children)}},19494:(i,e,o)=>{o.r(e),o.d(e,{assets:()=>l,contentTitle:()=>s,default:()=>u,frontMatter:()=>r,metadata:()=>a,toc:()=>c});const a=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/it/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17 aprile 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/it/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/it/2023/04/16"}}');var n=o(23420),t=o(3331);const r={localized_date:"17 aprile 2023",top_news:"De-Stressing Booking.com"},s="2023-04-17",l={},c=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"Ho usato Stable Diffusion e Dreambooth per creare un ritratto artistico del mio cane.",id:"ho-usato-stable-diffusion-e-dreambooth-per-creare-un-ritratto-artistico-del-mio-cane",level:2},{value:"Il traffic shaping di AT&amp;T Wireless sembra rendere inutilizzabili alcuni siti web",id:"il-traffic-shaping-di-att-wireless-sembra-rendere-inutilizzabili-alcuni-siti-web",level:2},{value:"Future Blues - La pagina di Emily su Cowboy Bebop (1999)",id:"future-blues---la-pagina-di-emily-su-cowboy-bebop-1999",level:2},{value:"Salmone in lavastoviglie",id:"salmone-in-lavastoviglie",level:2},{value:"Pico3D: Motore di gioco 3D a mondo aperto per il sistema Pico (microcontrollore RP2040)",id:"pico3d-motore-di-gioco-3d-a-mondo-aperto-per-il-sistema-pico-microcontrollore-rp2040",level:2},{value:"Wayback: Servizio di archiviazione self-hosted integrato con Internet Archive",id:"wayback-servizio-di-archiviazione-self-hosted-integrato-con-internet-archive",level:2},{value:"La pi\xf9 veloce libreria di composizione matematica per il web",id:"la-pi\xf9-veloce-libreria-di-composizione-matematica-per-il-web",level:2},{value:"&quot;Algebra per nessuno&quot; fallisce a San Francisco",id:"algebra-per-nessuno-fallisce-a-san-francisco",level:2},{value:"La FSF critica Google per l&#39;abbandono di JPEG-XL in Chrome",id:"la-fsf-critica-google-per-labbandono-di-jpeg-xl-in-chrome",level:2}];function d(i){const e={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...i.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,n.jsx)(e.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Originale"}),".\nL'autore condivide un'opinione sull'uso eccessivo di tattiche di persuasione nei siti web di e-commerce, in particolare Booking.com, e presenta la sua estensione per Chrome, \"De-stresser\", che rimuove i messaggi e le notifiche che inducono stress da Booking.com, offrendo agli utenti un'esperienza pi\xf9 piacevole. Nascondendo i tag di persuasione e modificando il linguaggio in modo che risulti pi\xf9 positivo, De-stresser consente agli utenti un'esperienza di prenotazione pi\xf9 tranquilla e rilassata. L'estensione \xe8 ora disponibile e utilizzabile su Booking.com."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),".\nBooking.com sta affrontando critiche per l'uso di tattiche di vendita ad alta pressione, tra cui messaggi di urgenza e pop-up che possono scoraggiare gli utenti. I critici sostengono che questo approccio privilegia le metriche a breve termine rispetto alla fedelt\xe0 a lungo termine dei clienti. Gli utenti riferiscono di aver trovato il modo di aggirare queste tattiche, anche utilizzando estensioni per bloccarle o filtrarle. Nel frattempo, gli utenti di Discussion Service discutono i meriti dei test A/B, alcuni dei quali sottolineano la possibilit\xe0 di creare \"modelli oscuri\" sui siti web. Nonostante queste preoccupazioni, molti utenti continuano a utilizzare aggregatori di prenotazioni come Booking.com ed Expedia, per comodit\xe0 o perch\xe9 offrono prezzi e politiche di cancellazione favorevoli. Alcuni esperti avvertono che prenotare direttamente con gli hotel pu\xf2 offrire migliori opzioni di risoluzione delle controversie, mentre altri sottolineano che i tassi di commissione dei siti di prenotazione possono variare notevolmente a seconda dell'hotel. Tuttavia, i programmi di fidelizzazione degli hotel possono offrire vantaggi significativi a chi viaggia spesso."]}),"\n",(0,n.jsx)(e.h2,{id:"ho-usato-stable-diffusion-e-dreambooth-per-creare-un-ritratto-artistico-del-mio-cane",children:"Ho usato Stable Diffusion e Dreambooth per creare un ritratto artistico del mio cane."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Originale"}),".\nL'articolo parla dell'uso delle tecniche di IA Stable Diffusion e Dreambooth per creare un ritratto dipinto di alta qualit\xe0 di un cane. L'autore condivide l'intero flusso di lavoro e fornisce istruzioni dettagliate su come addestrare un modello Dreambooth sulle foto del proprio cane. L'articolo parla anche dell'uso dell'upscaling per ingrandire le immagini di piccole dimensioni per ottenere stampe di alta qualit\xe0 e presenta la Stable Diffusion come una novit\xe0 assoluta per il mondo dell'arte generativa da testo a immagine."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nUn utente di Discussion Service ha utilizzato Stable Diffusion e Dreambooth per creare un ritratto artistico del proprio cane, mentre i commenti hanno discusso le reazioni contro l'AI art e i dibattiti su copyright e fair use. L'uso dell'IA generativa per l'arte presenta questioni etiche relative alla legge sul copyright e al fair use, con opinioni discordanti in merito. Alcuni hanno criticato Stable Diffusion per l'uso di opere d'arte rubate senza compenso come dati di addestramento, mentre altri hanno lodato la tecnologia e il suo potenziale per ulteriori innovazioni nel settore."]}),"\n",(0,n.jsx)(e.h2,{id:"il-traffic-shaping-di-att-wireless-sembra-rendere-inutilizzabili-alcuni-siti-web",children:"Il traffic shaping di AT&T Wireless sembra rendere inutilizzabili alcuni siti web"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Originale"}),'.\nIl piano "illimitato" a 100 Mbit di AT&T con 50 GB di dati prioritari potrebbe essere soggetto a un traffic shaping aggressivo, causando l\'inutilizzabilit\xe0 di alcuni siti web, mentre un test ha dimostrato che una scheda SIM di Verizon non presenta lo stesso problema. Il traffico Akamai mostra prove di manipolazione intenzionale del flusso TCP. Il traffic shaping interessa solo gli account solo dati degli account business.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless starebbe strozzando gli indirizzi IP di alcuni siti di streaming video, rendendo inutilizzabili alcuni siti web e causando discrepanze nei test di velocit\xe0 di Internet. Gli utenti hanno suggerito soluzioni come la presentazione di un reclamo alla FCC, l'utilizzo di una VPN per bypassare il throttling o la scelta di un altro APN. Alcuni commentatori sono scettici sul fatto che dietro il throttling si celino intenti nefasti, mentre altri propongono soluzioni come limiti di velocit\xe0 o declassamento della qualit\xe0 video per preservare l'allocazione dei dati."]}),"\n",(0,n.jsx)(e.h2,{id:"future-blues---la-pagina-di-emily-su-cowboy-bebop-1999",children:"Future Blues - La pagina di Emily su Cowboy Bebop (1999)"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://futureblues.com/",children:"Originale"}),".\nSpiacente, non c'\xe8 un testo da riassumere."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nGli utenti di Discussion Service esprimono nostalgia per i design originali e creativi dei siti web classici, contrapponendoli alla natura standardizzata, rumorosa e monetizzata dei siti web moderni, suggerendo un desiderio di paesaggi mediatici pi\xf9 artistici e incentrati sull'individualit\xe0. Emergono punti di discussione che mettono a confronto Wikipedia e Fandom, e la distinzione tra siti per dispositivi mobili e siti per soli desktop, e il design del sito web ispira sia nostalgia che stupore per la sua longevit\xe0. Nel complesso, il post offre uno sguardo ai ricordi degli utenti dei primi anni di Internet e fornisce una piattaforma per discutere lo stato attuale del web."]}),"\n",(0,n.jsx)(e.h2,{id:"salmone-in-lavastoviglie",children:"Salmone in lavastoviglie"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Originale"}),".\nIl salmone in lavastoviglie \xe8 un piatto di pesce preparato avvolgendo pezzi di salmone in almeno due strati di carta d'alluminio e mettendolo in lavastoviglie durante il ciclo di lavaggio e asciugatura. Il metodo \xe8 stato dimostrato per la prima volta negli Stati Uniti da Vincent Price nel 1975 e da allora \xe8 stato presentato in vari media. Tuttavia, ci sono preoccupazioni circa la consistenza delle temperature in lavastoviglie, che pu\xf2 portare a una cottura incompleta e a potenziali rischi per la salute."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nUn articolo di Hacker News sulla cottura del salmone in lavastoviglie scatena un dibattito sulla sicurezza del metodo di cottura, con utenti del settore della sicurezza alimentare che controbattono alle affermazioni di uno YouTuber. Sebbene la sicurezza della cottura in lavastoviglie dipenda da diversi fattori, per uccidere i batteri nel salmone sono necessari almeno 63\xb0C per 15 secondi."]}),"\n",(0,n.jsx)(e.h2,{id:"pico3d-motore-di-gioco-3d-a-mondo-aperto-per-il-sistema-pico-microcontrollore-rp2040",children:"Pico3D: Motore di gioco 3D a mondo aperto per il sistema Pico (microcontrollore RP2040)"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Originale"}),".\nIl motore di gioco Pico3D utilizza il secondo core dell'RP2040 come rasterizzatore/GPU dedicato per eseguire un gioco 3D open world completo su un microcontrollore da 1 dollaro. Il motore contiene una piccola citt\xe0 e una periferia con zombie sparabili, con tutorial Blender disponibili per la creazione di mondi di gioco. La simulazione del motore include attualmente 50 PNG e 50 zombi contemporaneamente, con rendering ottimizzato con la distanza e il culling del frustum della vista."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nUn nuovo motore di gioco 3D, chiamato Pico3D, \xe8 stato sviluppato per il microcontrollore RP2040 con un display da 120x120px, che non dispone di memoria e RAM video sufficienti ma ha un'API unificata. Gli hacker sono entusiasti dei modi creativi di utilizzare il Pico/RP2040, e l'applicazione unica dei chip RAM nel frame buffer fa risaltare questo articolo sul sito tecnologico."]}),"\n",(0,n.jsx)(e.h2,{id:"wayback-servizio-di-archiviazione-self-hosted-integrato-con-internet-archive",children:"Wayback: Servizio di archiviazione self-hosted integrato con Internet Archive"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/wabarc/wayback",children:"Originale"}),".\nWayback \xe8 uno strumento di archiviazione self-hosted che ha l'obiettivo di catturare le pagine web in capsule temporali. \xc8 gratuito, open-source, multipiattaforma e consente una pi\xf9 facile integrazione con varie piattaforme, tra cui Internet Archive, archive.today, IPFS e Telegraph. Offre inoltre diverse opzioni di installazione, tra cui GitHub, Snapcraft, APT, RPM e Homebrew."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nIl servizio di archiviazione self-hosted di Wabarc archivia le pagine web in "capsule temporali" e memorizza i file per l\'uso offline; tuttavia, gli utenti di Discussion Service criticano il README poco chiaro e la mancanza di documentazione. Altri progetti simili includono ArchiveBox, Shiori, DiskerNet e SingleFile; HTTrack Website Copier \xe8 consigliato per scaricare localmente un intero sito web, mentre Browsertrix/Brozzler esegue il crawling con i browser senza testa per verificarne la precisione. Un utente di Discussion Service raccomanda The Old Net per la navigazione con browser vecchi/moderni senza JS, mentre il repo linkato necessita di maggiore chiarezza sulla condivisibilit\xe0 e sugli standard di archiviazione stabiliti.']}),"\n",(0,n.jsx)(e.h2,{id:"la-pi\xf9-veloce-libreria-di-composizione-matematica-per-il-web",children:"La pi\xf9 veloce libreria di composizione matematica per il web"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://katex.org/",children:"Originale"}),".\nKaTeX \xe8 una libreria di composizione matematica veloce per il web, che offre un layout di qualit\xe0 di stampa basato su TeX di Donald Knuth, non ha dipendenze e pu\xf2 essere facilmente integrata con le risorse del sito web per il rendering lato server utilizzando Node.js. La sua semplice API rende in modo efficiente le espressioni matematiche, anche in pagine con espressioni multiple, senza limitazioni di browser o di ambiente, ed \xe8 open source sotto la licenza MIT."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, la pi\xf9 veloce libreria di composizione matematica per il web, non supporta i diagrammi, il che la rende inadatta ad alcuni matematici, mentre MathJax e AsciiMath hanno entrambi progetti simili. \xc8 stato condiviso un sito web di confronto e gli utenti di Hacker News stanno discutendo sulle prestazioni e sulla praticit\xe0 di adattare il markup a contesti diversi."]}),"\n",(0,n.jsx)(e.h2,{id:"algebra-per-nessuno-fallisce-a-san-francisco",children:'"Algebra per nessuno" fallisce a San Francisco'}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Originale"}),".\nSecondo uno studio condotto da professori di Stanford, la politica del distretto scolastico di San Francisco \"Algebra per nessuno\" non \xe8 riuscita a migliorare i risultati degli studenti neri e ispanici in matematica avanzata, con il risultato di un aumento del divario nei risultati. La decisione di rimandare l'algebra al nono anno e di mettere nelle stesse classi studenti con risultati bassi e alti non ha aiutato gli studenti con risultati bassi e ha reso pi\xf9 difficile il successo degli studenti con risultati alti. Le famiglie che possono permetterselo si sono rivolte a corsi online o a scuole private. Un gruppo di genitori ha intentato una causa contro il distretto, sostenendo che viola la legge statale sull'accesso equo alla matematica avanzata."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nLa politica di San Francisco di ritardare l'algebra fino al nono anno e di mettere nelle stesse classi studenti con risultati bassi, medi e alti \xe8 stata criticata, e alcuni suggeriscono che i concetti matematici fondamentali dovrebbero essere insegnati prima. Alcuni utenti di Discussion Service suggeriscono di incentivare i successi accademici ed extrascolastici collegandoli a ricompense finanziarie, mentre altri sostengono che sovvenzionare l'istruzione superiore attraverso sistemi di crediti per pagare l'universit\xe0 pi\xf9 tardi sarebbe una soluzione migliore. Ci sono dibattiti sull'utilit\xe0 dell'insegnamento tradizionale della matematica e sull'efficacia dell'aumento dei fondi per ridurre le dimensioni delle classi, con alcuni utenti che suggeriscono di insegnare la matematica attraverso problemi di ingegneria e i vantaggi dell'istruzione online."]}),"\n",(0,n.jsx)(e.h2,{id:"la-fsf-critica-google-per-labbandono-di-jpeg-xl-in-chrome",children:"La FSF critica Google per l'abbandono di JPEG-XL in Chrome"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Originale"}),'.\nLa Free Software Foundation critica la decisione di Google di abbandonare il supporto JPEG-XL in Chrome, sottolineando la necessit\xe0 di una scelta del browser e di formati multimediali liberi. Nonostante il clamore della comunit\xe0, gli ingegneri di Google sono andati avanti con la decisione, che rimane una delle questioni pi\xf9 "stellate" nella storia del progetto Chromium. Gli utenti hanno dimostrato un forte sostegno a JPEG-XL, ma l\'attenzione di Google per il controllo rispetto alla libert\xe0 sembra prevalere.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle \xe8 stata criticata dalla Free Software Foundation per aver interrotto il supporto a JPEG-XL in Chrome, nonostante sia stato adottato dai principali editor di immagini. Alcuni utenti sostengono che i vecchi formati come PNG e JPEG sono sufficienti, mentre altri preferiscono codec come AVIF per i video. Il dibattito verte sulla fattibilit\xe0 e sull'adozione di nuovi formati di immagine nell'ecosistema, con il sostegno e l'interesse dell'industria per JPEG-XL, ma l'adozione dipende dal supporto di tutti i principali browser."]})]})}function u(i={}){const{wrapper:e}={...(0,t.R)(),...i.components};return e?(0,n.jsx)(e,{...i,children:(0,n.jsx)(d,{...i})}):d(i)}}}]);